 const selected=taskId?tasks.find(t=>t.id===taskId):tasks[0],scope=selected?.id||"",where=scope==="legacy-active"?" AND b.task_id='' AND b.status<>'done'":" AND b.task_id=?",args=scope==="legacy-active"?[owner]:[owner,scope];
